    r1.appendChild(actBtn(pdf ? 'Keep the PDF (retry)' : 'Save a copy here (retry)', 'primary', () => makeCopy(b.id, 'local')));
  }
  const r2 = el('div', 'cp-row'); const l2 = el('span', 'cp-label'); l2.textContent = 'Internet Archive'; r2.appendChild(l2);
  if (copies.ia) {
