  r1.appendChild(selAll);
  if (!allSel) { const clr = el('button', 'link'); clr.textContent = 'Clear'; clr.addEventListener('click', () => { selected.clear(); render(); }); r1.appendChild(clr); }
  bar.appendChild(r1);

  const acts = el('div', 'bulk-actions');
