test('quoted operator is literal text', () => {
  assert.deepEqual(run('"AND"'), ['Carbonara']);
});
test('boolean with grouping', () => {
  assert.deepEqual(run('rome (#article OR #book)'), ['Rome guidebook', 'Rome history']);
