test('malformed query reports error and falls back to words', () => {
  const f = Q.makeFilter('rome (');
  assert.equal(f.error, true);
  assert.deepEqual(items.filter(f.test).map(x => x.title).sort(), ['Rome guidebook', 'Rome history']);
});
